response.text:
{
  "title": "tBregs and Tumor Dynamics",
  "perWatchSecond": 10,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "tBregs Drive Tumor to Maximum Size",
      "goal": "Show that a high tBreg population forces the tumor to reach its carrying capacity despite active NK cells.",
      "control": {
        "parameter": "m_T",
        "label": "Tumor-induced tBreg growth rate",
        "lowEnd": "0 (no tBreg activation)",
        "highEnd": "1e-12 (strong tBreg activation)"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "What if tumor-induced tBreg growth is doubled?",
        "parameter": "m_T",
        "value": 1e-14
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "higher",
        "by": 10
      },
      "effect": "With increased tBreg growth, the tumor peak rises above 90, reaching near the carrying capacity, while with lower growth it stays below 80.",
      "prediction": {
        "prompt": "Will doubling m_T raise the tumor peak?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Headline Result",
        "quote": "a sufficiently large number of tBregs can cause the breast tumour to reach its carrying capacity, regardless of the rate of NK-induced breast cancer cell death."
      },
      "carryForward": "Keep NK cell parameters unchanged."
    },
    {
      "kind": "background",
      "finding": 2,
      "title": "NK Cells Control Tumor Without tBregs",
      "goal": "Demonstrate that without tBregs, tumor size depends on NK killing rate.",
      "control": {
        "parameter": "c",
        "label": "NK-induced tumor death rate",
        "lowEnd": "0 (no NK killing)",
        "highEnd": "5e-10 (high NK killing)"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "What if tBregs are absent?",
        "parameter": "b0",
        "value": 0
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 20
      },
      "effect": "Without tBregs, even strong NK activity keeps the tumor peak below 60, far under the carrying capacity seen with tBregs.",
      "prediction": {
        "prompt": "Will removing tBregs lower the tumor peak?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Tumor Control by NK",
        "quote": "when tBregs do not exist in the body, the only way for the breast tumour to reach its carrying capacity is for the rate of NK-induced breast cancer cell death to be tending to 0"
      },
      "carryForward": "Maintain the chosen c value."
    },
    {
      "kind": "idea",
      "finding": 4,
      "title": "NK Killing Rate Thresholds",
      "goal": "Identify the critical NK killing rates that shift tumor outcomes.",
      "control": {
        "parameter": "c",
        "label": "NK-induced tumor death rate",
        "lowEnd": "1e-10 (low killing)",
        "highEnd": "3e-10 (high killing)"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "What if NK killing rate crosses the first bifurcation threshold?",
        "parameter": "c",
        "value": 1.5e-10
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 15
      },
      "effect": "Crossing the threshold reduces the tumor peak from above 85 to below 70, illustrating tumor elimination versus persistence.",
      "prediction": {
        "prompt": "Will increasing c past the threshold lower the tumor peak?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Bifurcation Threshold",
        "quote": "System [reducedModel] experiences a transcritical bifurcation at the equilibrium point E1 ≡ E2 as the parameter c varies through c1."
      },
      "carryForward": "Keep tBreg parameters as in the previous level."
    },
    {
      "kind": "method",
      "finding": 5,
      "title": "tBreg Natural Death Dominates",
      "goal": "Show that rapid tBreg death prevents tumor escalation.",
      "control": {
        "parameter": "thetaB",
        "label": "tBreg natural death rate",
        "lowEnd": "0.3 (slow death)",
        "highEnd": "0.6 (fast death)"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "What if tBreg death rate is increased?",
        "parameter": "thetaB",
        "value": 0.6
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 12
      },
      "effect": "A higher tBreg death rate drops the tumor peak from near 95 to around 83, mimicking a tBreg‑free scenario.",
      "prediction": {
        "prompt": "Will a higher thetaB lower the tumor peak?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "tBreg Death Outpaces Activation",
        "quote": "when θB/mT > 1/b, our model has no closed orbits, meaning that breast cancer will either be cleared by NK cells or stabilise around a constant number."
      },
      "carryForward": "Use the same m_T as the hook level."
    },
    {
      "kind": "evaluation",
      "finding": 6,
      "title": "Cancer Dormancy Emerges",
      "goal": "Reveal how the system can settle into a low‑level dormant tumor state.",
      "control": {
        "parameter": "a",
        "label": "Tumor growth rate",
        "lowEnd": "0.05 (slow growth)",
        "highEnd": "0.25 (fast growth)"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "What if tumor growth rate is reduced?",
        "parameter": "a",
        "value": 0.08
      },
      "difference": {
        "compartment": "t",
        "summary": "mean",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 5
      },
      "effect": "Lowering the growth rate keeps the average tumor size under 10, illustrating dormancy, versus an average above 25 at higher growth.",
      "prediction": {
        "prompt": "Will reducing a lower the average tumor size?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Dormancy Phenomenon",
        "quote": "This phenomenon is known as cancer dormancy and it happens to 20–45% of breast cancer patients"
      },
      "carryForward": "Maintain all other parameters from the previous evaluation."
    }
  ],
  "limits": [
    "Time per level must not exceed 20 seconds at 4× speed.",
    "Difference in observed compartment must be at least 10% of chart height.",
    "At least 3 figures must differ between worlds in the town visualization."
  ]
}
